# =========================
# 1) Read data + basic checks
# =========================
file_path <- "/Users/ronnygottheway/Desktop/467 Spring/Projects/WorkSpace/data/raw/AB_NYC_2019.csv"

ab_raw <- read_csv(file_path, show_col_types = TRUE)

# Basic structure checks
dim(ab_raw)       # rows and columns
names(ab_raw)     # variable names
head(ab_raw)      # first 6 rows
str(ab_raw)       # structure and data types
summary(ab_raw)   # summary statistics

# =========================
# 2) Data cleaning
# =========================
# 2.1 Missing values overview (all variables)
missing_counts <- colSums(is.na(ab_raw))
missing_counts

# 2.2 Focus missing checks for key variables
ab_raw %>%
  summarise(
    missing_price = sum(is.na(price)),
    missing_reviews_per_month = sum(is.na(reviews_per_month)),
    missing_last_review = sum(is.na(last_review)),
    zero_price = sum(price == 0, na.rm = TRUE)
  )

# 2.3 Main variables for modeling
vars_needed <- c(
  "price", "room_type", "neighbourhood_group",
  "minimum_nights", "number_of_reviews", "reviews_per_month",
  "calculated_host_listings_count", "availability_365"
)

# Check if all required variables exist
setdiff(vars_needed, names(ab_raw))

# 2.4 Remove price == 0 and keep complete cases for model variables
ab_clean <- ab_raw %>%
  filter(!is.na(price), price > 0) %>%
  mutate(
    room_type = factor(room_type),
    neighbourhood_group = factor(neighbourhood_group)
  ) %>%
  filter(if_all(all_of(vars_needed), ~ !is.na(.x))) %>%
  mutate(log_price = log(price))

# Quick check after cleaning
dim(ab_clean)
summary(ab_clean$price)
summary(ab_clean$log_price)

# =========================
# 3) Variable selection + factor reference levels
# =========================
# Ensure selected variables exist in cleaned data
setdiff(c(vars_needed, "log_price"), names(ab_clean))

# Set reference groups as requested
ab_clean <- ab_clean %>%
  mutate(
    room_type = fct_relevel(room_type, "Private room"),
    neighbourhood_group = fct_relevel(neighbourhood_group, "Brooklyn")
  )

# Confirm levels
levels(ab_clean$room_type)
levels(ab_clean$neighbourhood_group)

# =========================
# 4) Data Analysis
# =========================

# 4.1 Descriptive statistics for quantitative variables
quant_vars <- c(
  "price", "log_price", "minimum_nights", "number_of_reviews",
  "reviews_per_month", "calculated_host_listings_count", "availability_365"
)

desc_stats <- ab_clean %>%
  select(all_of(quant_vars)) %>%
  summarise(
    across(
      everything(),
      list(
        mean = ~ mean(.x, na.rm = TRUE),
        median = ~ median(.x, na.rm = TRUE),
        sd = ~ sd(.x, na.rm = TRUE),
        min = ~ min(.x, na.rm = TRUE),
        q1 = ~ quantile(.x, 0.25, na.rm = TRUE),
        q3 = ~ quantile(.x, 0.75, na.rm = TRUE),
        max = ~ max(.x, na.rm = TRUE)
      ),
      .names = "{.col}_{.fn}"
    )
  )

desc_stats

# 4.2 Frequency + percentage tables for categorical variables
room_type_tab <- ab_clean %>%
  count(room_type) %>%
  mutate(percent = n / sum(n) * 100)

neigh_tab <- ab_clean %>%
  count(neighbourhood_group) %>%
  mutate(percent = n / sum(n) * 100)

room_type_tab
neigh_tab

# 4.3 Price distribution focus
summary(ab_clean$price)
quantile(ab_clean$price, probs = c(0, 0.25, 0.5, 0.75, 0.9, 0.95, 0.99, 1), na.rm = TRUE)

