# =========================
# 5) Linear Models (Multiple Regression)
# =========================

# Model 1: categorical predictors only
model1 <- lm(log_price ~ room_type + neighbourhood_group, data = ab_clean)
summary(model1)

# Model 2: add quantitative predictors
model2 <- lm(
  log_price ~ room_type + neighbourhood_group +
    minimum_nights + number_of_reviews + reviews_per_month +
    calculated_host_listings_count + availability_365,
  data = ab_clean
)
summary(model2)

# Tidy tables with 95% CI
m1_tidy <- tidy(model1, conf.int = TRUE, conf.level = 0.95)
m2_tidy <- tidy(model2, conf.int = TRUE, conf.level = 0.95)

m1_tidy
m2_tidy

# R-squared and Adjusted R-squared comparison
model_compare <- bind_rows(
  glance(model1) %>% mutate(model = "Model 1"),
  glance(model2) %>% mutate(model = "Model 2")
) %>%
  select(model, r.squared, adj.r.squared, sigma, statistic, p.value, df)

model_compare

# Nested-model comparison (ANOVA F-test)
anova(model1, model2)

# =========================
# 6) Coefficient interpretation helpers (log-price -> % change)
# =========================
# Percent interpretation function: 100*(exp(beta)-1)
interpret_percent <- function(beta) {
  100 * (exp(beta) - 1)
}

# Example: extract key coefficients from Model 2 and convert
key_coef <- broom::tidy(model2) %>%
  filter(grepl("room_type|neighbourhood_group", term)) %>%
  mutate(percent_change = interpret_percent(estimate))

key_coef

# =========================
# 7) Model diagnostics
# =========================

# Base R diagnostic panel
par(mfrow = c(2, 2))
plot(model2)
par(mfrow = c(1, 1))

# VIF for multicollinearity
vif_values <- car::vif(model2)
vif_values

# Cook's distance for influential points
cooks_d <- cooks.distance(model2)
summary(cooks_d)

# Common threshold: 4/n
n <- nrow(ab_clean)
cook_threshold <- 4 / n
influential_idx <- which(cooks_d > cook_threshold)
length(influential_idx)
head(influential_idx)

# Optional plot for Cook's D
plot(cooks_d, pch = 20, cex = 0.5, main = "Cook's Distance", ylab = "Cook's D")
abline(h = cook_threshold, col = "red", lty = 2)

# =========================
# 8) Inference + prediction
# =========================

# Significance + CI already in m2_tidy. If needed, print only key rows:
m2_tidy %>%
  filter(term != "(Intercept)") %>%
  arrange(p.value)

# Construct a new listing for prediction
new_listing <- tibble(
  neighbourhood_group = factor("Manhattan", levels = levels(ab_clean$neighbourhood_group)),
  room_type = factor("Entire home/apt", levels = levels(ab_clean$room_type)),
  minimum_nights = 3,
  number_of_reviews = 20,
  reviews_per_month = 1.5,
  calculated_host_listings_count = 2,
  availability_365 = 180
)

# Predicted log_price with CI and PI
pred_conf <- predict(model2, newdata = new_listing, interval = "confidence", level = 0.95)
pred_pred <- predict(model2, newdata = new_listing, interval = "prediction", level = 0.95)

pred_conf
pred_pred

# Convert from log scale back to price scale (exp transformation)
pred_price_conf <- exp(pred_conf)
pred_price_pred <- exp(pred_pred)

pred_price_conf
pred_price_pred

